package com.anonyser.itemid;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RepairCostsTest
{
	@Test
	public void loadsTheBundledCsvAndMatchesByNameCaseInsensitively()
	{
		final RepairCosts costs = RepairCosts.load();
		assertTrue(costs.size() > 40);
		assertEquals(Integer.valueOf(150000), costs.cost("Fighter torso"));
		assertEquals(Integer.valueOf(150000), costs.cost("fighter torso"));
		assertEquals(Integer.valueOf(240000), costs.cost("Dragon defender"));
	}

	@Test
	public void unknownOrNullItemsHaveNoCost()
	{
		final RepairCosts costs = RepairCosts.load();
		assertNull(costs.cost("Dragon dagger"));
		assertNull(costs.cost(null));
	}

	@Test
	public void skipsCommentsBlanksAndMalformedRows()
	{
		final RepairCosts costs = new RepairCosts();
		costs.add("# a comment");
		costs.add("   ");
		costs.add("No number here");
		costs.add("Bad cost,abc");
		costs.add("Good item,1234");
		assertEquals(1, costs.size());
		assertEquals(Integer.valueOf(1234), costs.cost("Good item"));
	}
}

package com.anonyser.itemid;

import java.util.HashMap;
import java.util.Map;
import static org.junit.Assert.assertArrayEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class RecipesTest
{
	@Test
	public void loadsTheBundledRecipesFile()
	{
		final Recipes recipes = Recipes.load();
		assertTrue(recipes.size() >= 10);
	}

	@Test
	public void resolvesResultAndComponentsToIds()
	{
		final Recipes recipes = new Recipes();
		recipes.add("Volatile nightmare staff|Nightmare staff|Volatile orb");

		final Map<String, Integer> names = new HashMap<>();
		names.put("volatile nightmare staff", 24422);
		names.put("nightmare staff", 24422 - 1);
		names.put("volatile orb", 24514);

		final Map<Integer, int[]> resolved = recipes.resolve(names);
		assertArrayEquals(new int[]{24421, 24514}, resolved.get(24422));
	}

	@Test
	public void dropsRecipesWithAnyUnresolvedName()
	{
		final Recipes recipes = new Recipes();
		recipes.add("Made thing|Known part|Unknown part");

		final Map<String, Integer> names = new HashMap<>();
		names.put("made thing", 100);
		names.put("known part", 101);
		// "unknown part" is absent

		assertFalse(recipes.resolve(names).containsKey(100));
	}

	@Test
	public void ignoresCommentsBlanksAndNonRecipeLines()
	{
		final Recipes recipes = new Recipes();
		recipes.add("# comment");
		recipes.add("   ");
		recipes.add("No pipe here");
		recipes.add("Result|Part");
		assertTrue(recipes.size() == 1);
	}
}

package com.anonyser.itemid;

import com.google.gson.Gson;
import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;
import static org.junit.Assert.assertTrue;
import org.junit.Test;

public class WikiDescriptionTest
{
	private final Gson gson = new Gson();

	@Test
	public void parsesTheExtractFromAMediaWikiResponse()
	{
		final String json = "{\"query\":{\"pages\":{\"12345\":{\"pageid\":12345,"
			+ "\"title\":\"Dragon dagger\",\"extract\":\"The dragon dagger is a dagger. \"}}}}";
		assertEquals("The dragon dagger is a dagger.", WikiDescription.parse(gson, json));
	}

	@Test
	public void returnsNullForMissingPagesOrJunk()
	{
		assertNull(WikiDescription.parse(gson, "{\"query\":{\"pages\":{\"-1\":{\"missing\":\"\"}}}}"));
		assertNull(WikiDescription.parse(gson, "{\"query\":{\"pages\":{\"1\":{\"extract\":\"\"}}}}"));
		assertNull(WikiDescription.parse(gson, "not json at all"));
		assertNull(WikiDescription.parse(gson, "{}"));
	}

	@Test
	public void buildsAWikiApiUrlWithTheItemNameAsTitle()
	{
		final String url = WikiDescription.url("Volatile nightmare staff").toString();
		assertTrue(url.startsWith("https://oldschool.runescape.wiki/api.php"));
		assertTrue(url.contains("prop=extracts"));
		assertTrue(url.contains("titles=Volatile%20nightmare%20staff")
			|| url.contains("titles=Volatile+nightmare+staff"));
	}
}

package com.anonyser.itemid;

import com.google.gson.Gson;
import com.google.inject.Provides;
import java.awt.BasicStroke;
import java.awt.Color;
import java.awt.Graphics2D;
import java.awt.RenderingHints;
import java.awt.image.BufferedImage;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import javax.swing.SwingUtilities;
import net.runelite.api.ChatMessageType;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.ItemComposition;
import net.runelite.api.MenuEntry;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GameTick;
import net.runelite.api.events.MenuEntryAdded;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.chat.ChatColorType;
import net.runelite.client.chat.ChatMessageBuilder;
import net.runelite.client.chat.ChatMessageManager;
import net.runelite.client.chat.QueuedMessage;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.game.ItemStats;
import net.runelite.client.plugins.Plugin;
