	private void onComparePick(int bId, String bName)
	{
		final int aId = selectedId;
		final String aName = selectedName;
		if (aId <= 0)
		{
			return;
		}
		compareResults.removeAll();
		compareResults.revalidate();
		compareResults.repaint();
		clientThread.invoke(() ->
		{
			final Snapshot a = snapshot(aId, aName);
			final Snapshot b = snapshot(bId, bName);
			SwingUtilities.invokeLater(() -> renderCompare(a, b));
		});
	}

	private Snapshot snapshot(int id, String name)
	{
		final ItemComposition c = itemManager.getItemComposition(id);
		final int ge = itemManager.getItemPrice(id);
		final int ha = c != null ? c.getHaPrice() : 0;
		final ItemStats s = itemManager.getItemStats(id);
		return new Snapshot(name, ge, ha, s != null ? s.getEquipment() : null);
	}

	private void renderCompare(Snapshot a, Snapshot b)
	{
		comparePanel.removeAll();
		comparePanel.add(cell("", ColorScheme.LIGHT_GRAY_COLOR, false));
		comparePanel.add(headerCell(shortName(a.name)));
		comparePanel.add(headerCell(shortName(b.name)));
		addValueRow("GE", a.ge, b.ge);
		addValueRow("Alch", a.ha, b.ha);
		if (a.eq != null && b.eq != null)
		{
			addCompareRow("Stab atk", a.eq.getAstab(), b.eq.getAstab(), true);
			addCompareRow("Slash atk", a.eq.getAslash(), b.eq.getAslash(), true);
			addCompareRow("Crush atk", a.eq.getAcrush(), b.eq.getAcrush(), true);
			addCompareRow("Magic atk", a.eq.getAmagic(), b.eq.getAmagic(), true);
			addCompareRow("Range atk", a.eq.getArange(), b.eq.getArange(), true);
			addCompareRow("Stab def", a.eq.getDstab(), b.eq.getDstab(), true);
			addCompareRow("Slash def", a.eq.getDslash(), b.eq.getDslash(), true);
			addCompareRow("Crush def", a.eq.getDcrush(), b.eq.getDcrush(), true);
			addCompareRow("Magic def", a.eq.getDmagic(), b.eq.getDmagic(), true);
			addCompareRow("Range def", a.eq.getDrange(), b.eq.getDrange(), true);
			addCompareRow("Str", a.eq.getStr(), b.eq.getStr(), true);
			addCompareRow("Ranged str", a.eq.getRstr(), b.eq.getRstr(), true);
			addCompareRow("Prayer", a.eq.getPrayer(), b.eq.getPrayer(), true);
			addMdmgRow(a.eq.getMdmg(), b.eq.getMdmg());
			addCompareRow("Speed", a.eq.getAspeed(), b.eq.getAspeed(), false);
		}
		comparePanel.setVisible(true);
		revalidate();
		repaint();
	}

	private void addValueRow(String label, int aVal, int bVal)
	{
		comparePanel.add(cell(label, ColorScheme.LIGHT_GRAY_COLOR, false));
		comparePanel.add(cell(aVal > 0 ? gp(aVal) : "-", ColorScheme.LIGHT_GRAY_COLOR, false));
		comparePanel.add(cell(bVal > 0 ? gp(bVal) : "-", ColorScheme.LIGHT_GRAY_COLOR, false));
	}

	private void addCompareRow(String label, int aVal, int bVal, boolean higherBetter)
	{
		final boolean aBetter = higherBetter ? aVal > bVal : aVal < bVal;
		final boolean bBetter = higherBetter ? bVal > aVal : bVal < aVal;
		comparePanel.add(cell(label, ColorScheme.LIGHT_GRAY_COLOR, false));
		comparePanel.add(cell(sign(aVal), aBetter ? BETTER : ColorScheme.LIGHT_GRAY_COLOR, aBetter));
		comparePanel.add(cell(sign(bVal), bBetter ? BETTER : ColorScheme.LIGHT_GRAY_COLOR, bBetter));
	}

	private void addMdmgRow(float aVal, float bVal)
	{
		final boolean aBetter = aVal > bVal;
		final boolean bBetter = bVal > aVal;
		comparePanel.add(cell("Magic dmg", ColorScheme.LIGHT_GRAY_COLOR, false));
		comparePanel.add(cell(signPct(aVal), aBetter ? BETTER : ColorScheme.LIGHT_GRAY_COLOR, aBetter));
		comparePanel.add(cell(signPct(bVal), bBetter ? BETTER : ColorScheme.LIGHT_GRAY_COLOR, bBetter));
	}

	private static JLabel cell(String text, Color color, boolean bold)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(color);
		label.setFont(bold ? FontManager.getRunescapeBoldFont() : FontManager.getRunescapeSmallFont());
		return label;
	}

	private static JLabel headerCell(String text)
	{
		final JLabel label = new JLabel(text);
		label.setForeground(Color.WHITE);
		label.setFont(FontManager.getRunescapeBoldFont());
		return label;
	}

	private static String shortName(String name)
	{
		return name != null && name.length() > 12 ? name.substring(0, 11) + "…" : name;
	}

	private static final class Snapshot
	{
		final String name;
		final int ge;
		final int ha;
		final ItemEquipmentStats eq;

		Snapshot(String name, int ge, int ha, ItemEquipmentStats eq)
		{
			this.name = name;
			this.ge = ge;
			this.ha = ha;
			this.eq = eq;
		}
	}

	private static String gp(int value)
	{
		return String.format("%,d gp", value);
	}

	/** The OSRS wiki page URL for an item name (the wiki uses underscores for spaces). */
	private static String wikiUrl(String name)
	{
		return "https://oldschool.runescape.wiki/w/" + name.replace(' ', '_');
	}
}

package com.anonyser.itemid;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.ArrayList;
import java.util.HashMap;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Combination recipes (a GE item built from other GE items), loaded by name from recipes.csv. The
 * data is only names; {@link #resolve} turns them into item ids using a name-to-id map built from the
 * game's own items, so an id is never guessed. A recipe whose result or any component can't be
 * resolved is dropped rather than shown wrong.
 */
class Recipes
{
	// result name (as written) -> component names
	private final Map<String, List<String>> byName = new LinkedHashMap<>();

	static Recipes load()
	{
		final Recipes r = new Recipes();
		try (InputStream in = Recipes.class.getResourceAsStream("/com/anonyser/itemid/recipes.csv"))
		{
			if (in != null)
			{
				try (BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
				{
					String line;
					while ((line = br.readLine()) != null)
					{
						r.add(line);
					}
				}
			}
		}
		catch (IOException e)
		{
			// leave whatever parsed
		}
		return r;
	}

	void add(String line)
	{
		if (line == null)
		{
			return;
		}
		final String trimmed = line.trim();
		if (trimmed.isEmpty() || trimmed.startsWith("#") || !trimmed.contains("|"))
		{
			return;
		}
		final String[] parts = trimmed.split("\\|");
		final String result = parts[0].trim();
		final List<String> components = new ArrayList<>();
		for (int i = 1; i < parts.length; i++)
		{
			final String c = parts[i].trim();
			if (!c.isEmpty())
			{
				components.add(c);
			}
		}
		if (!result.isEmpty() && !components.isEmpty())
		{
			byName.put(result, components);
		}
	}

	/**
	 * Resolves the loaded recipes to item ids using a lowercase-name to id map. Only recipes whose
	 * result and every component resolve are returned, keyed by the result item id.
	 */
	Map<Integer, int[]> resolve(Map<String, Integer> nameToId)
	{
		final Map<Integer, int[]> out = new HashMap<>();
		for (Map.Entry<String, List<String>> e : byName.entrySet())
		{
			final Integer resultId = nameToId.get(e.getKey().toLowerCase());
			if (resultId == null || resultId <= 0)
			{
				continue;
			}
			final List<String> names = e.getValue();
			final int[] ids = new int[names.size()];
			boolean ok = true;
			for (int i = 0; i < names.size(); i++)
			{
				final Integer cid = nameToId.get(names.get(i).toLowerCase());
				if (cid == null || cid <= 0)
				{
					ok = false;
					break;
				}
				ids[i] = cid;
			}
			if (ok)
			{
				out.put(resultId, ids);
			}
		}
		return out;
	}

	int size()
	{
		return byName.size();
	}
}

package com.anonyser.itemid;

import java.io.BufferedReader;
import java.io.IOException;
import java.io.InputStream;
import java.io.InputStreamReader;
import java.nio.charset.StandardCharsets;
import java.util.HashMap;
import java.util.Map;

/**
 * Repair-on-death (broken) costs for untradeables, looked up by item name. The data is the same
 * OSRS-wiki-verified list the PvP profit tracker uses; here it just adds a "repair" figure to the
 * item lookup. Lines are "item name,cost"; blank lines and lines starting with # are ignored.
 */
class RepairCosts
{
	private final Map<String, Integer> costs = new HashMap<>();

	static RepairCosts load()
	{
		final RepairCosts r = new RepairCosts();
		try (InputStream in = RepairCosts.class.getResourceAsStream("/com/anonyser/itemid/repair-costs.csv"))
		{
			if (in != null)
			{
				try (BufferedReader br = new BufferedReader(new InputStreamReader(in, StandardCharsets.UTF_8)))
				{
					String line;
					while ((line = br.readLine()) != null)
					{
						r.add(line);
					}
				}
			}
		}
		catch (IOException e)
		{
			// leave whatever parsed; a missing repair figure just isn't shown
		}
		return r;
	}

	void add(String line)
	{
		if (line == null)
		{
			return;
		}
		final String trimmed = line.trim();
		if (trimmed.isEmpty() || trimmed.startsWith("#"))
		{
			return;
		}
		final int comma = trimmed.lastIndexOf(',');
		if (comma <= 0 || comma == trimmed.length() - 1)
		{
			return;
		}
		final String name = trimmed.substring(0, comma).trim().toLowerCase();
		try
		{
			costs.put(name, Integer.parseInt(trimmed.substring(comma + 1).trim()));
		}
		catch (NumberFormatException e)
		{
			// skip a malformed row rather than fail the whole file
		}
	}

	/** The repair cost for an item name, or null if it isn't a known repairable untradeable. */
	Integer cost(String itemName)
	{
		return itemName == null ? null : costs.get(itemName.toLowerCase());
	}

	int size()
	{
		return costs.size();
	}
}

package com.anonyser.itemid;

import com.google.gson.Gson;
import com.google.gson.JsonElement;
import com.google.gson.JsonObject;
import java.io.IOException;
import java.util.Map;
import java.util.concurrent.ConcurrentHashMap;
import okhttp3.Call;
import okhttp3.HttpUrl;
import okhttp3.OkHttpClient;
import okhttp3.Request;
import okhttp3.Response;
import okhttp3.ResponseBody;

/**
 * Fetches a short item description from the OSRS wiki (the intro of the item's page) through the
 * MediaWiki API. A request is made only when an item is clicked, and each item's result is cached
 * for the session. URL building and JSON parsing are pure and unit-tested; the network call is
 * async and never blocks the UI. A failed or empty lookup just leaves the description off.
 */
class WikiDescription
{
	private static final HttpUrl API = HttpUrl.get("https://oldschool.runescape.wiki/api.php");

	interface Callback
	{
		void onResult(int id, String description);
	}

	private final OkHttpClient http;
	private final Gson gson;
	private final Map<Integer, String> cache = new ConcurrentHashMap<>();

	WikiDescription(OkHttpClient http, Gson gson)
	{
		this.http = http;
		this.gson = gson;
	}

	void fetch(int id, String itemName, Callback cb)
	{
		final String cached = cache.get(id);
		if (cached != null)
		{
			cb.onResult(id, cached);
			return;
		}
		final Request request = new Request.Builder().url(url(itemName)).build();
		http.newCall(request).enqueue(new okhttp3.Callback()
		{
			@Override
			public void onFailure(Call call, IOException e)
			{
				// a lookup failure isn't worth surfacing; the description just stays off
			}

			@Override
			public void onResponse(Call call, Response response)
			{
				try (ResponseBody body = response.body())
				{
					if (body != null)
					{
						final String desc = parse(gson, body.string());
						if (desc != null)
						{
							cache.put(id, desc);
							cb.onResult(id, desc);
						}
					}
				}
				catch (Exception e)
				{
					// ignore malformed responses
				}
			}
		});
	}

	static HttpUrl url(String itemName)
	{
		return API.newBuilder()
			.addQueryParameter("action", "query")
			.addQueryParameter("format", "json")
			.addQueryParameter("prop", "extracts")
			.addQueryParameter("exintro", "1")
			.addQueryParameter("explaintext", "1")
			.addQueryParameter("exsentences", "3")
			.addQueryParameter("redirects", "1")
			.addQueryParameter("titles", itemName)
			.build();
	}

	/** Pulls the first page's plaintext extract out of a MediaWiki query response, or null. */
	static String parse(Gson gson, String json)
	{
		try
		{
			final JsonObject root = gson.fromJson(json, JsonObject.class);
			final JsonObject query = root != null ? root.getAsJsonObject("query") : null;
			final JsonObject pages = query != null ? query.getAsJsonObject("pages") : null;
			if (pages == null)
			{
				return null;
			}
			for (Map.Entry<String, JsonElement> e : pages.entrySet())
			{
				final JsonObject page = e.getValue().getAsJsonObject();
				if (page.has("extract"))
				{
					final String extract = page.get("extract").getAsString();
					if (extract != null && !extract.trim().isEmpty())
					{
						return extract.trim();
					}
				}
			}
		}
		catch (RuntimeException e)
		{
			// unexpected shape -> no description
		}
		return null;
	}
}
